let lang = 'de';
export function setLang(l) { lang = l === 'en' ? 'en' : 'de'; document.documentElement.lang = lang; }
export function getLang() { return lang; }
export function t(key, vars = {}) {
  const s = (lang === 'en' ? en[key] : de[key]) ?? de[key] ?? key;
  // Unknown placeholders stay as they are (e.g. {{text}} in the webhook help)
  return String(s).replace(/(?<!\{)\{(\w+)\}(?!\})/g, (all, k) => (k in vars ? String(vars[k] ?? '') : all));
}

// Reasons of the device recognition (the server names them in English)
const REASONS_DE = { "Apple device without services": "Apple-Gerät ohne Dienste", "Hyper-V network card": "Hyper-V-Netzwerkkarte", "LANCOM access point": "LANCOM Access Point", "LANCOM switch": "LANCOM-Switch", "Mac": "Mac", "NAS web interface": "Weboberfläche eines NAS", "Proxmox web interface": "Proxmox-Weboberfläche", "SMB/NetBIOS": "SMB/NetBIOS", "UPS": "USV", "VoIP phone": "VoIP-Telefon", "Windows with remote desktop": "Windows mit Remotedesktop", "access point name": "Name eines Access Points", "camera": "Kamera", "database port": "Datenbank-Port", "default gateway": "Standard-Gateway", "domain controller (Kerberos, LDAP, DNS)": "Domänencontroller (Kerberos, LDAP, DNS)", "firewall web interface": "Weboberfläche einer Firewall", "mail server port": "Mailserver-Port", "name of a card terminal": "Name eines Kartenterminals", "port 4742 (SICCT)": "Port 4742 (SICCT)", "port 515 (LPD)": "Port 515 (LPD)", "port 554 (RTSP)": "Port 554 (RTSP)", "port 631 (IPP)": "Port 631 (IPP)", "port 8006 (Proxmox VE)": "Port 8006 (Proxmox VE)", "port 8007 (Proxmox Backup Server)": "Port 8007 (Proxmox Backup Server)", "port 9100 (raw printing)": "Port 9100 (Direktdruck)", "ports 5000/5001": "Ports 5000/5001", "printer name": "Name eines Druckers", "private (random) MAC address": "private (zufällige) MAC-Adresse", "smart home": "Smart Home", "switch name": "Name eines Switches", "this server (runs WhatsOnMyNet)": "dieser Server (hier läuft WhatsOnMyNet)", "web interface of a TI connector": "Weboberfläche eines TI-Konnektors" };
const REASON_PREFIX_DE = {"PC manufacturer ": "PC-Hersteller ", "network manufacturer ": "Netzwerk-Hersteller ", "printer manufacturer ": "Drucker-Hersteller ", "virtual network card ": "virtuelle Netzwerkkarte ", "manufacturer ": "Hersteller "};
export function reasonText(r) {
  if (lang === 'en') return r;
  if (REASONS_DE[r]) return REASONS_DE[r];
  for (const [en, de] of Object.entries(REASON_PREFIX_DE)) if (r.startsWith(en)) return de + r.slice(en.length);
  return r;
}
export const KEYS_DE = Object.keys(de);
export const KEYS_EN = Object.keys(en);
